CREATE ROLE app_owner LOGIN PASSWORD 'AppOwner#2026';
CREATE ROLE report_user LOGIN PASSWORD 'Report#2026';
CREATE DATABASE shopdb OWNER app_owner;
\c shopdb
SET ROLE app_owner;
CREATE SCHEMA sales;
CREATE TABLE sales.customers (
  customer_id   bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  full_name     text NOT NULL,
  city          text NOT NULL
);
CREATE TABLE sales.orders (
  order_id      bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  customer_id   bigint NOT NULL REFERENCES sales.customers,
  order_date    date NOT NULL,
  amount        numeric(10,2) NOT NULL
);
CREATE TABLE sales.payments (
  payment_id    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  order_id      bigint NOT NULL REFERENCES sales.orders,
  paid_on       date NOT NULL,
  method        text NOT NULL
);
CREATE INDEX orders_customer_idx ON sales.orders (customer_id);
INSERT INTO sales.customers (full_name, city)
SELECT 'Customer ' || g, (ARRAY['Hyderabad','Pune','Chennai','Delhi'])[1 + g % 4]
FROM generate_series(1, 1000) AS g;
INSERT INTO sales.orders (customer_id, order_date, amount)
SELECT 1 + g % 1000, date '2026-01-01' + g % 300, round((100 + random() * 9900)::numeric, 2)
FROM generate_series(1, 50000) AS g;
INSERT INTO sales.payments (order_id, paid_on, method)
SELECT order_id, order_date + 1, (ARRAY['UPI','card','netbanking'])[1 + order_id % 3]
FROM sales.orders WHERE order_id % 5 <> 0;
CREATE VIEW sales.daily_revenue AS
SELECT order_date, sum(amount) AS revenue FROM sales.orders GROUP BY order_date;
GRANT USAGE ON SCHEMA sales TO report_user;
GRANT SELECT ON ALL TABLES IN SCHEMA sales TO report_user;
RESET ROLE;

